/**
 * release-to-content.mjs — turn a release into draft content inputs.
 *
 *   pnpm marketing:release-notes 0.22.1
 *
 * Writes a filled-in source-event worksheet to marketing/content/drafts/. It
 * drafts; it does not publish. Nothing here posts to a social network, opens a
 * discussion, or sends an email, and it should stay that way: the value of this
 * project's voice comes from a human deciding a thing is worth saying.
 *
 * The generated file deliberately leaves the insight blank. A release is not an
 * insight — "we shipped X" is an announcement, and announcements do not travel.
 * The worksheet exists to force the question "what did this teach anyone?".
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const read = (p) => JSON.parse(readFileSync(`${root}/${p}`, "utf8"));

const version = process.argv[2]?.replace(/^v/, "");
if (!version) {
  console.error("usage: pnpm marketing:release-notes <version>   e.g. 0.22.1");
  process.exit(2);
}

const manifest = read("components.manifest.json");
const parity = read("platform-parity.json");
const blocks = read("block-parity.json");
const defs = manifest.platformDefinitions;
const componentTotal = Object.keys(manifest.components).length;
const fullCoverage = Object.values(parity.components).filter((ps) => parity.catalogPlatforms.every((p) => ps.includes(p))).length;

/** Components whose `since` is this release — the only "new in this version" claim we can prove. */
const newComponents = Object.entries(manifest.components)
  .filter(([, c]) => c.since === version)
  .map(([slug]) => slug);

const coverageRows = Object.entries(defs)
  .map(([name, d]) => `| ${d.label} | ${parity.coverage[name]} / ${componentTotal} | ${d.family} | ${d.maturity} |`)
  .join("\n");

const out = `# Release ${version} → content

_Generated by \`pnpm marketing:release-notes ${version}\` on ${new Date().toISOString().slice(0, 10)}._
_Numbers below are read from generated repository data at generation time. Re-check with \`pnpm marketing:stats\` before publishing._

## Verified numbers at this release

| Platform | Components | Family | Maturity |
| --- | --- | --- | --- |
${coverageRows}

- ${fullCoverage} of ${componentTotal} components on all ${parity.catalogPlatforms.length} complete-catalogue platforms
- Blocks: ${blocks.total} total — ${Object.entries(blocks.coverage).map(([k, v]) => `${k} ${v}`).join(", ")}
- New components in ${version}: ${newComponents.length ? newComponents.join(", ") : "none"}

## Release note (developer-facing — no marketing language here)

- **What changed:**
- **Why it matters:**
- **Who benefits:**
- **Migration impact:**
- **Affected platforms:**
- **Docs / components touched:**

## The insight

One sentence, and not "we shipped X". What would someone who will never use
KinetixUI still find worth knowing?

> …

## Draft outputs

| Output | Status | Angle |
| --- | --- | --- |
| LinkedIn post | todo | |
| X post or thread | todo | |
| Long-form article | todo | |
| Demo clip | todo | |
| GitHub release body | todo | |
| Docs change | todo | |

## Claims check

- [ ] Numbers re-read from \`pnpm marketing:stats\` on the day of publishing
- [ ] No install command for a package that is not published
- [ ] Preview platforms described as preview
- [ ] No parity claim beyond what the coverage table supports
- [ ] No invented adoption, customers or testimonials
`;

const dir = `${root}/marketing/content/drafts`;
if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
const path = `marketing/content/drafts/release-${version}.md`;
writeFileSync(`${root}/${path}`, out);
console.log(`wrote ${path} — a draft worksheet, not a publication.`);
console.log(`  ${componentTotal} components · ${fullCoverage} on all ${parity.catalogPlatforms.length} catalogue platforms · ${newComponents.length} new in ${version}`);
